const item = $input.first().json;
const payload = item.body ? item.body : item;

// Trích xuất dữ liệu vé từ Luồng 3 Sub-workflow hoặc direct packet
const ticketCode = String(payload.ticket_code || payload.downstream_bridge?.ticket_code || 'TK-' + new Date().toISOString().slice(0, 10).replace(/-/g, '') + '-0001').trim();
const customerEmail = String(payload.customer_email || payload.downstream_bridge?.customer_email || payload.sender_email || 'client@enterprise.com').trim().toLowerCase();
const subject = String(payload.subject || payload.title || 'Hỗ trợ kỹ thuật hệ thống').trim();
const priority = String(payload.priority || 'P2 - High').trim();
const issueDescription = String(payload.issue_description || payload.technical_summary || payload.downstream_bridge?.technical_summary || payload.clean_body || payload.body || payload.reproduce_steps || subject).trim();

// Trích xuất từ khóa kỹ thuật cốt lõi và làm sạch stopwords
const combinedText = `${subject} ${issueDescription}`;
const words = combinedText
  .replace(/<[^>]*>/g, ' ')
  .replace(/[.,/#!$%^&*;:{}=\-_`~()?\"'\n\r\t]/g, ' ')
  .split(/\s+/)
  .map(w => w.trim().toLowerCase())
  .filter(w => w.length > 1);

const stopwords = new Set([
  'the', 'and', 'for', 'you', 'are', 'this', 'that', 'with', 'from', 'have', 'your',
  'cua', 'cho', 'mot', 'nhung', 'toi', 'ban', 'la', 'va', 'cac', 'duoc', 'xin', 'hoi',
  'giup', 've', 'co', 'khong', 'nay', 'da', 'dang', 'se', 'bi', 'do', 'tai', 'tren'
]);

const technicalKeywords = [...new Set(words.filter(w => !stopwords.has(w)))].slice(0, 15);
const queryText = technicalKeywords.length > 0 ? technicalKeywords.join(' ') : subject;

return [{
  json: {
    ...payload,
    ticket_code: ticketCode,
    customer_email: customerEmail,
    subject: subject,
    priority: priority,
    issue_description: issueDescription,
    query_keywords: technicalKeywords,
    query_text: queryText
  }
}];

